content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Procurement Officer",
      "description": "Employee responsible for sourcing and purchasing raw logs from suppliers."
    },
    {
      "name": "Supplier Offer",
      "description": "Proposal from a forest supplier detailing price, volume, and type of logs available."
    },
    {
      "name": "Forest Supplier",
      "description": "External partner providing raw logs to the company."
    },
    {
      "name": "Log Shipment",
      "description": "Delivery of raw logs from a supplier to the sawmill.",
      "attributes": [
        "Raw Log"
      ]
    },
    {
      "name": "Raw Log",
      "description": "Unprocessed wood received from suppliers.",
      "attributes": [
        "Type",
        "Quality"
      ]
    },
    {
      "name": "Type",
      "description": "Specifies the tree species or wood category of the log."
    },
    {
      "name": "Quality",
      "description": "Indicates the grade or condition of the wood material."
    },
    {
      "name": "Sawmill Operator",
      "description": "Worker who processes raw logs into lumber according to production orders."
    },
    {
      "name": "Production Order",
      "description": "Instruction defining what type and amount of lumber should be produced."
    },
    {
      "name": "Production Output",
      "description": "Resulting batch of processed lumber from a production run.",
      "attributes": [
        "Lumber"
      ]
    },
    {
      "name": "Lumber",
      "description": "Processed wood product ready for storage or sale."
    },
    {
      "name": "Warehouse Supervisor",
      "description": "Employee managing storage, inventory, and shipment preparation of lumber."
    },
    {
      "name": "Stock Record",
      "description": "Inventory entry tracking lumber quantities and storage locations.",
      "attributes": [
        "Lumber",
        "Location"
      ]
    },
    {
      "name": "Location",
      "description": "Specific place or area in the warehouse where lumber is stored."
    },
    {
      "name": "Lumber Batch",
      "description": "Grouped collection of lumber units prepared for delivery.",
      "attributes": [
        "Lumber"
      ]
    },
    {
      "name": "Sales Representative",
      "description": "Staff member handling customer orders and communication."
    },
    {
      "name": "Customer Order",
      "description": "Initial purchase request made by a customer for lumber products."
    },
    {
      "name": "Customer",
      "description": "Buyer placing orders for lumber or related products."
    },
    {
      "name": "Sales Order",
      "description": "Confirmed internal record of a customer's purchase to be fulfilled."
    },
    {
      "name": "Status Update",
      "description": "Information provided to a customer regarding the progress of their order."
    },
    {
      "name": "Logistics Coordinator",
      "description": "Planner responsible for organizing deliveries and coordinating drivers."
    },
    {
      "name": "Lumber Delivery",
      "description": "Scheduled transport of lumber batches to a customer's destination.",
      "attributes": [
        "Lumber Batch",
        "Destination",
        "Load Size",
        "Delivery Documents"
      ]
    },
    {
      "name": "Destination",
      "description": "Delivery address or client location where lumber is sent."
    },
    {
      "name": "Load Size",
      "description": "Total volume or weight of lumber to be delivered."
    },
    {
      "name": "Delivery Documents",
      "description": "Papers accompanying shipments such as delivery notes and transport manifests."
    },
    {
      "name": "Delivery Completion Report",
      "description": "Record confirming that a delivery has been successfully completed."
    },
    {
      "name": "Driver",
      "description": "Person responsible for transporting lumber batches to customers."
    }
  ]
}
```
